SELECT /*LGSETC00060.retrieveMsgList*/ message_type_code , system_message_id , message_desc , NVL(language_code,'KO') AS language_code , message_detail_content FROM LGCOM_SYSTEM_MESSAGE_M WHERE 1 = 1
AND message_type_code = #{messageType}
AND (UPPER(system_message_id) LIKE '%' || UPPER(#{messageId}) || '%')
AND (UPPER(message_desc) LIKE '%' || UPPER(#{messageName}) || '%')
AND language_code = #{languageCode}
ORDER BY system_message_id, language_code

mapper.update:
/*LGSETC00060.updateMsgList*/
	UPDATE LGCOM_SYSTEM_MESSAGE_M
	   SET message_type_code      = #{messageTypeCode}
	     , message_desc   		  = #{messageDesc}
	     , message_detail_content = #{messageDetailContent}
	     , last_updated_by    	  = #{sessionUserId}
	     , last_update_date    	  = SYSDATE
	 WHERE system_message_id = #{systemMessageId}
	   AND language_code = #{languageCode}

/*LGSETC00060.deleteMsgList*/
	DELETE FROM LGCOM_SYSTEM_MESSAGE_M
	 WHERE system_message_id = #{systemMessageId}
	   AND language_code = #{languageCode}

